def get_current_user_id(token: str=Depends(oauth2_scheme), conn=Depends(get_db)) -> uuid.UUID:
    """Verifies incoming JWT tokens and validates that the user exists in our DB layout."""
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=[ALGORITHM])
        email: str = payload.get('sub')
        if email is None:
            raise HTTPException(status_code=401, detail='Token validation payload failed.')
    except jwt.PyJWTError:
        raise HTTPException(status_code=401, detail='Token has expired or is corrupt.')
    cursor = conn.cursor()
    cursor.execute('SELECT id FROM users WHERE email = %s;', (email,))
    user_record = cursor.fetchone()
    cursor.close()
    if not user_record:
        raise HTTPException(status_code=404, detail='User account no longer found within database context.')
    return user_record[0]

@app.post('/register', status_code=status.HTTP_201_CREATED)
def register_user(user: UserRegister, conn=Depends(get_db)):
    cursor = conn.cursor()
    cursor.execute('SELECT id FROM users WHERE email = %s;', (user.email,))
    if cursor.fetchone():
        cursor.close()
        raise HTTPException(status_code=400, detail='Email is already registered inside the citadel.')
    hashed_password = bcrypt.hashpw(user.password.encode('utf-8'), bcrypt.gensalt()).decode('utf-8')
    try:
        cursor.execute('INSERT INTO users (email, password_hash) VALUES (%s, %s);', (user.email, hashed_password))
        conn.commit()
        return {'status': 'success', 'message': 'User securely registered into database.'}
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f'Database execution error: {str(e)}')
    finally:
        cursor.close()

@app.post('/token', response_model=Token)
def login_for_access_token(form_data: OAuth2PasswordRequestForm=Depends(), conn=Depends(get_db)):
    cursor = conn.cursor()
    cursor.execute('SELECT id, password_hash FROM users WHERE email = %s;', (form_data.username,))
    user_record = cursor.fetchone()
    cursor.close()
    if not user_record or not pwd_context.verify(form_data.password, str(user_record[1])):
        raise HTTPException(status_code=401, detail='Invalid security credentials provided.')
    expire = datetime.now(timezone.utc) + timedelta(minutes=ACCESS_TOKEN_EXPIRE_MINUTES)
    to_encode = {'sub': form_data.username, 'exp': expire}
    encoded_jwt = jwt.encode(to_encode, SECRET_KEY, algorithm=ALGORITHM)
    return {'access_token': encoded_jwt, 'token_type': 'bearer'}

@app.post('/accounts', status_code=status.HTTP_201_CREATED)
def create_ledger_account(account_data: AccountCreateRequest, user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Initializes a new isolated financial asset, liability, or equity bucket with a target currency tag."""
    valid_types = {'Asset', 'Liability', 'Equity', 'Revenue', 'Expense'}
    if account_data.type.capitalize() not in valid_types:
        raise HTTPException(status_code=400, detail=f"Invalid ledger type. Must be one of: {', '.join(valid_types)}")
    cursor = conn.cursor()
    account_id = uuid.uuid4()
    currency_code = account_data.currency.upper()[:3]
    try:
        cursor.execute('INSERT INTO accounts (id, user_id, name, type, currency) \n               VALUES (%s, %s, %s, %s, %s);', (str(account_id), str(user_id), account_data.name, account_data.type.capitalize(), currency_code))
        conn.commit()
        return {'status': 'success', 'message': f'Ledger account bucket [{currency_code}] securely established.', 'account_id': account_id, 'account_name': account_data.name, 'currency': currency_code}
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f'Failed to create asset bucket: {str(e)}')
    finally:
        cursor.close()

@app.post('/transactions', status_code=status.HTTP_201_CREATED)
def post_balanced_transaction(tx_data: TransactionRequest, user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Enforces strict banking validation: entries must balance to 0 AND accounts must have sufficient liquidity."""
    net_sum = sum((entry.amount for entry in tx_data.entries))
    if net_sum != 0:
        raise HTTPException(status_code=400, detail=f'Transaction processing rejected: Unbalanced entries. Total net sum is {net_sum} cents. Must equal exactly 0.')
    cursor = conn.cursor()
    transaction_id = uuid.uuid4()
    try:
        for entry in tx_data.entries:
            cursor.execute('SELECT type FROM accounts WHERE id = %s AND user_id = %s;', (str(entry.account_id), str(user_id)))
            account_record = cursor.fetchone()
            if not account_record:
                raise HTTPException(status_code=403, detail=f'Access denied: Target account context {entry.account_id} is missing or belongs to another client.')
            account_type = account_record[0]
            if account_type == 'Asset' and entry.amount < 0:
                balance_query = '\n                    SELECT COALESCE(SUM(amount), 0) \n                    FROM journal_entries \n                    WHERE account_id = %s;\n                '
                cursor.execute(balance_query, (str(entry.account_id),))
                current_balance = cursor.fetchone()[0]
                if current_balance + entry.amount < 0:
                    raise HTTPException(status_code=400, detail=f'Transaction rejected: Insufficient funds in Asset account {entry.account_id}. Current Balance: {current_balance} cents. Attempted withdrawal: {abs(entry.amount)} cents.')
        for entry in tx_data.entries:
            cursor.execute('INSERT INTO journal_entries (transaction_id, account_id, description, amount) \n                   VALUES (%s, %s, %s, %s);', (str(transaction_id), str(entry.account_id), entry.description, entry.amount))
        conn.commit()
        return {'status': 'success', 'transaction_id': transaction_id, 'entries_logged': len(tx_data.entries)}
    except HTTPException:
        conn.rollback()
        raise
    except Exception as e:
        conn.rollback()
        raise HTTPException(status_code=500, detail=f'Database operational failure: {str(e)}')
    finally:
        cursor.close()

@app.get('/balances')
def get_account_balances(user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Computes real-time financial positions across all user asset buckets segmented by currency tag."""
    cursor = conn.cursor()
    query = '\n        SELECT a.id, a.name, a.type, a.currency, COALESCE(SUM(j.amount), 0) as current_balance\n        FROM accounts a\n        LEFT JOIN journal_entries j ON a.id = j.account_id\n        WHERE a.user_id = %s\n        GROUP BY a.id, a.name, a.type, a.currency;\n    '
    cursor.execute(query, (str(user_id),))
    records = cursor.fetchall()
    cursor.close()
    balances_report = []
    for row in records:
        balances_report.append({'account_id': row[0], 'account_name': row[1], 'account_type': row[2], 'currency': row[3], 'balance_raw_cents': row[4], 'balance_formatted': f'{row[3]} ${row[4] / 100:,.2f}' if row[3] != 'BTC' else f'₿{row[4] / 100000000:,.8f}'})
    return {'user_id': user_id, 'ledger_positions': balances_report}

@app.get('/transactions', response_model=List[JournalEntryResponse])
def get_transaction_history(limit: int=20, offset: int=0, user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Retrieves a paginated chronological audit log of all financial ledger items belonging to the client."""
    cursor = conn.cursor()
    query = '\n        SELECT j.id, j.transaction_id, j.account_id, a.name, j.description, j.amount\n        FROM journal_entries j\n        JOIN accounts a ON j.account_id = a.id\n        WHERE a.user_id = %s\n        ORDER BY j.id DESC\n        LIMIT %s OFFSET %s;\n    '
    try:
        cursor.execute(query, (str(user_id), limit, offset))
        records = cursor.fetchall()
        history = []
        for row in records:
            history.append({'entry_id': uuid.UUID(row[0]), 'transaction_id': uuid.UUID(row[1]), 'account_id': uuid.UUID(row[2]), 'account_name': row[3], 'description': row[4], 'amount_cents': row[5], 'amount_formatted': f'${row[5] / 100:,.2f}'})
        return history
    except Exception as e:
        raise HTTPException(status_code=500, detail=f'Failed to fetch transaction history: {str(e)}')
    finally:
        cursor.close()

@app.get('/reports/balance-sheet')
def get_balance_sheet_report(user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Generates a structured balance sheet verifying that Assets = Liabilities + Equity across all tracked currencies."""
    cursor = conn.cursor()
    query = "\n        SELECT a.type, a.currency, COALESCE(SUM(j.amount), 0) as total_cents\n        FROM accounts a\n        LEFT JOIN journal_entries j ON a.id = j.account_id\n        WHERE a.user_id = %s AND a.type IN ('Asset', 'Liability', 'Equity')\n        GROUP BY a.type, a.currency;\n    "
    try:
        cursor.execute(query, (str(user_id),))
        records = cursor.fetchall()
        report = {}
        for row in records:
            acct_type, currency, total = (row[0], row[1], row[2])
            if currency not in report:
                report[currency] = {'assets': 0, 'liabilities': 0, 'equity': 0, 'equation_balanced': False}
            if acct_type == 'Asset':
                report[currency]['assets'] = total
            elif acct_type == 'Liability':
                report[currency]['liabilities'] = total
            elif acct_type == 'Equity':
                report[currency]['equity'] = total
        for curr, balances in report.items():
            if balances['assets'] == balances['liabilities'] + balances['equity']:
                balances['equation_balanced'] = True
        return {'user_id': user_id, 'balance_sheet_by_currency': report}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f'Failed to compile balance sheet: {str(e)}')
    finally:
        cursor.close()

@app.get('/reports/income-statement')
def get_income_statement_report(user_id: uuid.UUID=Depends(get_current_user_id), conn=Depends(get_db)):
    """Computes operational net profit or loss by subtracting total expenses from total revenues."""
    cursor = conn.cursor()
    query = "\n        SELECT a.type, a.currency, COALESCE(SUM(j.amount), 0) as total_cents\n        FROM accounts a\n        LEFT JOIN journal_entries j ON a.id = j.account_id\n        WHERE a.user_id = %s AND a.type IN ('Revenue', 'Expense')\n        GROUP BY a.type, a.currency;\n    "
    try:
        cursor.execute(query, (str(user_id),))
        records = cursor.fetchall()
        report = {}
        for row in records:
            acct_type, currency, total = (row[0], row[1], row[2])
            if currency not in report:
                report[currency] = {'total_revenue_cents': 0, 'total_expense_cents': 0, 'net_income_cents': 0}
            if acct_type == 'Revenue':
                report[currency]['total_revenue_cents'] = total
            elif acct_type == 'Expense':
                report[currency]['total_expense_cents'] = total
        for curr, flows in report.items():
            flows['net_income_cents'] = flows['total_revenue_cents'] - flows['total_expense_cents']
            flows['net_income_formatted'] = f"{curr} ${flows['net_income_cents'] / 100:,.2f}"
        return {'user_id': user_id, 'income_statement_by_currency': report}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f'Failed to compile income statement: {str(e)}')
    finally:
        cursor.close()

